# Deploy-Changes.ps1
# Applies last 2 commits of dino-application changes.
# Run from the root of the dino-application folder.

$ErrorActionPreference = "Stop"
$root = $PSScriptRoot
if (-not $root) { $root = Get-Location }

$files = @(
    @{ Path = "Dockerfile"; B64 = "" },
    @{ Path = "requirements.txt"; B64 = "" },
    @{ Path = "src\Main.py"; B64 = "" },
    @{ Path = "src\application\routes\Areas.py"; B64 = "" },
    @{ Path = "src\application\routes\Auth.py"; B64 = "" },
    @{ Path = "src\application\routes\Categories.py"; B64 = "" },
    @{ Path = "src\application\routes\Customers.py"; B64 = "" },
    @{ Path = "src\application\routes\Dashboard.py"; B64 = "" },
    @{ Path = "src\application\routes\HomePage.py"; B64 = "" },
    @{ Path = "src\application\routes\Items.py"; B64 = "" },
    @{ Path = "src\application\routes\Orders.py"; B64 = "" },
    @{ Path = "src\application\routes\Personas.py"; B64 = "" },
    @{ Path = "src\application\routes\Reviews.py"; B64 = "" },
    @{ Path = "src\application\routes\Tables.py"; B64 = "" },
    @{ Path = "src\application\routes\Workspaces.py"; B64 = "" },
    @{ Path = "src\application\services\Billing.py"; B64 = "" },
    @{ Path = "src\application\services\Customer.py"; B64 = "" },
    @{ Path = "src\application\services\Dashboard.py"; B64 = "" },
    @{ Path = "src\application\services\Order.py"; B64 = "" },
    @{ Path = "src\application\services\Review.py"; B64 = "" },
    @{ Path = "src\base\BaseAuth.py"; B64 = "" },
    @{ Path = "src\base\BaseModel.py"; B64 = "" },
    @{ Path = "src\base\BaseRepository.py"; B64 = "" },
    @{ Path = "src\base\BaseRoleCheck.py"; B64 = "" },
    @{ Path = "src\base\BaseSchema.py"; B64 = "" },
    @{ Path = "src\base\BaseService.py"; B64 = "" },
    @{ Path = "src\config\Database.py"; B64 = "" },
    @{ Path = "src\config\Settings.py"; B64 = "" },
    @{ Path = "src\core\Dependencies.py"; B64 = "" },
    @{ Path = "src\core\Security.py"; B64 = "" },
    @{ Path = "src\models\Area.py"; B64 = "" },
    @{ Path = "src\models\Base.py"; B64 = "" },
    @{ Path = "src\models\BillingTransaction.py"; B64 = "" },
    @{ Path = "src\models\Category.py"; B64 = "" },
    @{ Path = "src\models\Order.py"; B64 = "" },
    @{ Path = "src\models\OrderDetail.py"; B64 = "" },
    @{ Path = "src\models\OrderTransaction.py"; B64 = "" },
    @{ Path = "src\models\Persona.py"; B64 = "" },
    @{ Path = "src\models\Role.py"; B64 = "" },
    @{ Path = "src\models\Table.py"; B64 = "" },
    @{ Path = "src\models\User.py"; B64 = "" },
    @{ Path = "src\models\Workspace.py"; B64 = "" },
    @{ Path = "src\repositories\AreaRepository.py"; B64 = "" },
    @{ Path = "src\repositories\CategoryRepository.py"; B64 = "" },
    @{ Path = "src\repositories\CustomerRepository.py"; B64 = "" },
    @{ Path = "src\repositories\ItemRepository.py"; B64 = "" },
    @{ Path = "src\repositories\OrderRepository.py"; B64 = "" },
    @{ Path = "src\repositories\PermissionRepository.py"; B64 = "" },
    @{ Path = "src\repositories\PersonaRepository.py"; B64 = "" },
    @{ Path = "src\repositories\ReviewRepository.py"; B64 = "" },
    @{ Path = "src\repositories\RoleRepository.py"; B64 = "" },
    @{ Path = "src\repositories\TableRepository.py"; B64 = "" },
    @{ Path = "src\repositories\UserRepository.py"; B64 = "" },
    @{ Path = "src\repositories\WorkspaceRepository.py"; B64 = "" },
    @{ Path = "src\schemas\Area.py"; B64 = "" },
    @{ Path = "src\schemas\Auth.py"; B64 = "" },
    @{ Path = "src\schemas\Billing.py"; B64 = "" },
    @{ Path = "src\schemas\Category.py"; B64 = "" },
    @{ Path = "src\schemas\Customer.py"; B64 = "" },
    @{ Path = "src\schemas\Item.py"; B64 = "" },
    @{ Path = "src\schemas\Order.py"; B64 = "" },
    @{ Path = "src\schemas\Persona.py"; B64 = "" },
    @{ Path = "src\schemas\Review.py"; B64 = "" },
    @{ Path = "src\schemas\Table.py"; B64 = "" },
    @{ Path = "src\schemas\User.py"; B64 = "" }
)

foreach ($entry in $files) {
    $target = Join-Path $root $entry.Path
    $dir = Split-Path $target -Parent
    if (-not (Test-Path $dir)) { New-Item -ItemType Directory -Path $dir -Force | Out-Null }
    $bytes = [System.Convert]::FromBase64String($entry.B64)
    [System.IO.File]::WriteAllBytes($target, $bytes)
    Write-Host "  Written: $($entry.Path)"
}

Write-Host ""
Write-Host "All $($files.Count) files written successfully." -ForegroundColor Green